var DATA = {"step": "Map joints", "joints": "hip:10,knee:25,ankle:-5", "scale": "1.0"};
console.log("Retarget step: " + DATA.step);
// sample_joints like "hip:10,knee:25,ankle:-5" (source angles in degrees)
var scale = parseFloat(DATA.scale);
var joints = DATA.joints.split(",").map(function (s) {
  var p = s.split(":"); return { name: p[0].trim(), angle: parseFloat(p[1]) };
});
console.log("Source skeleton angles (deg): " + joints.map(function (j) { return j.name + "=" + j.angle; }).join(", "));
console.log("Target scale factor: " + scale);
// retarget: scale root translation effect; clamp joint angles to anatomical limits
var limits = { hip: 120, knee: 140, ankle: 50 };
var out = joints.map(function (j) {
  var lim = limits[j.name] || 180;
  var a = Math.max(-lim, Math.min(lim, j.angle));
  return { name: j.name, angle: a };
});
console.log("Retargeted (clamped) angles: " + out.map(function (j) { return j.name + "=" + j.angle; }).join(", "));
console.log("RESULT: " + out.length + " joints retargeted to scale " + scale + " with anatomical clamps.");

